  const LETTERS = ['A', 'B', 'C', 'D'];
  const ROMAN = ['I', 'II', 'III', 'IV'];

  const APPROACHES = [
    { key: 'quantitative', label: 'Quantitative evaluation', block: 'quantitative' },
    { key: 'series', label: 'Series completion', block: 'series' },
    { key: 'substitution', label: 'Corrective substitution', block: 'substitution' },
    { key: 'component', label: 'Component identification', block: 'component' },
  ];

  const levelFor = index => LEVELS[Math.min(4, Math.floor(index / 20))];

  /* ------------------------------------------------------------------ */
  /* List-I / List-II matching tables                                    */
  /* ------------------------------------------------------------------ */

  const formatMapping = mapping => mapping.map((value, index) => `${LETTERS[index]}-${ROMAN[value]}`).join(', ');

  function matchingOptions(pair, seed) {
    const keyed = formatMapping(pair);
    const rotate = mapping => mapping.map((_, index) => mapping[(index + 1) % mapping.length]);
    const swap = mapping => {
      const copy = mapping.slice();
      const at = seed % (copy.length - 1);
      const held = copy[at];
      copy[at] = copy[at + 1];
      copy[at + 1] = held;
      return copy;
    };
    const reverse = mapping => mapping.slice().reverse();

    const options = [keyed];
    for (const candidate of [rotate, swap, reverse]) {
      const text = formatMapping(candidate(pair));
      if (!options.includes(text)) options.push(text);
    }
    let step = 1;
    while (options.length < 4) {
      const text = formatMapping(pair.map((_, index) => (pair[index] + step) % pair.length));
      if (!options.includes(text)) options.push(text);
      step += 1;
    }
    return options.slice(0, 4);
  }

